/**
 * Generates docs/rules.md from rule metadata, so the docs cannot drift from
 * the code (CI regenerates and fails on a diff). Run: npm run docs
 */
import { writeFileSync } from "node:fs";
import { format } from "prettier";
import { fileURLToPath } from "node:url";
import { builtinRules } from "../src/rules/index.js";

const lines: string[] = [
  "# Rules",
  "",
  "<!-- Generated by `npm run docs` from rule metadata. Do not edit by hand. -->",
  "",
  "Codes are grouped by hundreds: 0xx server surface, 1xx descriptions, 2xx God Tool, 3xx annotations, 4xx naming, 5xx security signals. ✅ = in `mcpsmell:recommended`. 🧪 = preview rule (needs `--preview` or `linterOptions.preview`).",
  "",
  "| Code | Rule | Description | Default | |",
  "| ---- | ---- | ----------- | ------- | - |",
];
for (const { meta } of builtinRules) {
  const flags = `${meta.recommended ? "✅" : ""}${meta.stability === "preview" ? "🧪" : ""}`;
  lines.push(
    `| ${meta.code} | [${meta.id}](#${meta.id}) | ${meta.docs.description} | ${meta.defaultSeverity} | ${flags} |`,
  );
}
for (const { meta } of builtinRules) {
  lines.push(
    "",
    `## ${meta.id}`,
    "",
    `**${meta.code}** · ${meta.type} · ${meta.category} · ${meta.stability}`,
    "",
  );
  lines.push(meta.docs.description, "", meta.docs.rationale, "", `Source: ${meta.docs.source}`, "");
  const options = meta.defaultOptions ?? {};
  if (Object.keys(options).length > 0) {
    lines.push(
      "Options (defaults shown):",
      "",
      "```json",
      JSON.stringify({ [meta.id]: ["warn", options] }, null, 2),
      "```",
      "",
    );
  }
  lines.push("Messages:", "");
  for (const message of Object.values(meta.messages))
    lines.push(`- ${message.replace(/\{\{\s*(\w+)\s*\}\}/g, "`<$1>`")}`);
}
const out = fileURLToPath(new URL("../../docs/rules.md", import.meta.url));
writeFileSync(
  out,
  await format(`${lines.join("\n")}\n`, {
    parser: "markdown",
    printWidth: 100,
    proseWrap: "preserve",
  }),
);
console.log(`wrote ${out}`);
